from pathlib import Path

def replace_once(s, old, new, label):
    n = s.count(old)
    if n != 1:
        raise SystemExit(f"ABORTADO ({label}): esperava 1 ocorrencia, encontrei {n}. Nada foi alterado.")
    return s.replace(old, new)

if not Path("api/_cronlib.js").exists():
    raise SystemExit("ABORTADO (raiz-errada): rode este script na raiz do projeto denise-os (onde tem a pasta api/).")

